"""Original family-of-origin documentation fields. No score or diagnostic inference."""
from modules.questionnaires import digest
GROUPS =[{'key': 'raised_by', 'label': 'Family Background / Raised By', 'choices': ['Biological mother', 'Biological father', 'Adoptive parent(s)', 'Stepparent(s)', 'Grandparent(s)', 'Other relatives', 'Foster parent(s)', 'Older sibling(s)', 'Other caregiver(s)', 'Institutional / residential care', 'History unknown']}, {'key': 'relatives', 'label': 'Relatives With Reported Health Concerns', 'choices': ['Mother', 'Father', 'Sibling(s)', 'Maternal grandparent(s)', 'Paternal grandparent(s)', 'Other biological relatives', 'Adoptive / step / foster family', 'Other caregiver(s)', 'No known concerns reported', 'History unknown']}, {'key': 'medical', 'label': 'Family Medical / Health History', 'choices': ['Heart / cardiovascular disease', 'High blood pressure', 'Diabetes', 'Cancer', 'Stroke', 'Seizure disorder', 'Other neurological condition', 'Dementia / memory disorder', 'Thyroid / endocrine condition', 'Respiratory disease', 'Chronic pain', 'Significant disability', 'Genetic / inherited condition', 'Other medical condition', 'No known concerns reported', 'History unknown']}, {'key': 'mental_health', 'label': 'Family Mental Health History', 'choices': ['Depression', 'Bipolar disorder', 'Anxiety / panic', 'Psychotic disorder', 'Trauma-related concerns', 'Eating disorder', 'Attention / developmental concerns', 'Mental health treatment', 'Psychiatric hospitalization', 'Suicide attempt(s)', 'Death by suicide', 'Other mental health concerns', 'No known concerns reported', 'History unknown']}, {'key': 'substance', 'label': 'Family Substance-Use History', 'choices': ['Alcohol-related concerns', 'Drug / nonmedical prescription-use concerns', 'Substance-use treatment', 'Recovery / sobriety', 'Other substance-use concerns', 'No known concerns reported', 'History unknown']}, {'key': 'marital', 'label': 'Parental / Caregiver Marital and Partnership History', 'choices': ['Married', 'Unmarried partners', 'Single-parent household', 'Separated', 'Divorced', 'Remarried / blended family', 'Widowed caregiver', 'Multiple marriages / changes in partnerships', 'Other arrangement', 'History unknown']}, {'key': 'relationships', 'label': 'Family Relationships', 'choices': ['Emotional support / close family relationships', 'Positive caregiver relationship(s)', 'Open communication', 'Limited emotional expression', 'Frequent arguments / conflict', 'High criticism / rejection', 'Limited contact / estrangement', 'Other relationship pattern', 'Extended-family support', 'Shared activities / traditions', 'Supportive sibling relationship(s)', 'Effective conflict resolution', 'Limited family support', 'No known concerns reported', 'History unknown']}, {'key': 'stability', 'label': 'Family Stability During Upbringing', 'choices': ['Stable housing', 'Consistent caregiver(s)', 'Predictable routines', 'Financial stability', 'Frequent moves', 'Housing insecurity / homelessness', 'Financial hardship', 'Caregiver absence / prolonged separation', 'Foster care / placement changes', 'Caregiver incarceration', 'Family illness / disability affected stability', 'Significant family loss / bereavement', 'Domestic violence / unsafe conflict', 'Abuse reported', 'Neglect reported', 'Other instability', 'Practical / financial support', 'Community / faith support', 'History unknown']}]
EXCLUSIVE=['No known concerns reported','History unknown']
NOTES={'health_notes':'Family Health Details / Affected Relatives','marital_notes':'Marital / Partnership Details','stability_notes':'Family Stability Details','other_notes':'Other Family Background / Source of Information'}
MOVED_SUPPORT={'Reliable emotional support': 'relationships', 'Extended-family support': 'relationships', 'Shared activities / traditions': 'relationships', 'Supportive sibling relationship(s)': 'relationships', 'Effective conflict resolution': 'relationships', 'Limited family support': 'relationships', 'Practical / financial support': 'stability', 'Community / faith support': 'stability'}
DEFINITION={'version':'2.0.0','consolidation_version':'1','groups':GROUPS,'notes':NOTES,'exclusive':EXCLUSIVE,'moved_support':MOVED_SUPPORT}
def validate(data):
    selections=data.get('selections')
    notes=data.get('notes',{})
    if not isinstance(selections,dict) or not isinstance(notes,dict):raise ValueError('Invalid family history form.')
    if set(selections)-{g['key'] for g in GROUPS} or set(notes)-set(NOTES):raise ValueError('Unknown family history field.')
    clean={}
    for group in GROUPS:
        choices=selections.get(group['key'],[])
        if not isinstance(choices,list) or any(not isinstance(v,str) or v not in group['choices'] for v in choices) or len(choices)!=len(set(choices)):raise ValueError('Choose supported family history items without duplicates.')
        if any(v in EXCLUSIVE for v in choices) and len(choices)>1:raise ValueError('Unknown / no known concerns cannot be combined with other items in the same section.')
        clean[group['key']]=choices
    text={}
    for key in NOTES:
        value=notes.get(key,'')
        if not isinstance(value,str) or len(value)>4000:raise ValueError('Family history notes must be at most 4000 characters per field.')
        text[key]=value.strip()
    return {'schema':'biopsychosocial-family-origin/1','selections':clean,'notes':text,'definition':DEFINITION,'definition_hash':digest(DEFINITION),'synthetic':True}
